def factor(n):
    d = 2
    while d * d <= n:
        if n % d == 0:
            return d, n // d
        d += 1
    return n, 1

print(factor(77))

def mystery(n):
    for k in range(2, int(n ** 0.5) + 1):
        if n % k == 0:
            return k, n // k
    return None

print(mystery(143))

def knapsack(weights, values, capacity):
    best = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        for c in range(capacity, w - 1, -1):
            best[c] = max(best[c], best[c - w] + v)
    return best[capacity]

print(knapsack([3, 4, 5, 2], [30, 50, 60, 20], 8))

